// Text analysis pipeline replicating the observed behavior of whoosh's
// StandardAnalyzer: RegexTokenizer (\w+) -> LowercaseFilter
// -> StopFilter(stoplist=STOP_WORDS, minsize=2, renumber=True).

export const STOP_WORDS = new Set([
  "a", "an", "and", "are", "as", "at", "be", "but", "by",
  "for", "if", "in", "into", "is", "it", "no", "not", "of",
  "on", "or", "such", "that", "the", "their", "then", "there",
  "these", "they", "this", "to", "was", "will", "with",
]);

const WORD_RE = /[\p{L}\p{N}_]+/gu;

export const MIN_SIZE = 2;

// Split raw text into lowercase tokens, dropping stop words and tokens
// shorter than MIN_SIZE. The returned array's indexes are the renumbered
// term positions (positions are compressed after filtering).
export function analyze(text) {
  if (typeof text !== "string" || text.length === 0) return [];
  const raw = text.match(WORD_RE);
  if (raw === null) return [];
  const terms = [];
  for (const token of raw) {
    const word = token.toLowerCase();
    if (word.length < MIN_SIZE) continue;
    if (STOP_WORDS.has(word)) continue;
    terms.push(word);
  }
  return terms;
}

// Filters only (no tokenization): used for wildcard and range endpoint
// text, which is lowercased and subjected to the stop-word / min-size
// filters but kept as a single string. Returns null when filtered out.
export function analyzeFilters(text) {
  const word = text.toLowerCase();
  if (word.length < MIN_SIZE) return null;
  if (STOP_WORDS.has(word)) return null;
  return word;
}

