// Query node types. Each query exposes match(index) returning a Set of
// document numbers (0-based insertion order).

function allDocs(index) {
  const set = new Set();
  for (let i = 0; i < index.docs.length; i++) set.add(i);
  return set;
}

function wildcardToRegex(pattern) {
  let src = "";
  for (const ch of pattern) {
    if (ch === "*") src += ".*";
    else if (ch === "?") src += ".";
    else src += ch.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }
  return new RegExp(`^${src}$`, "u");
}

export function NullQuery() {
  return { kind: "null", match: () => new Set() };
}

export function Term(field, text) {
  return {
    kind: "term",
    field,
    text,
    match(index) {
      const set = new Set();
      index.docs.forEach((doc, i) => {
        if (doc[field].includes(text)) set.add(i);
      });
      return set;
    },
  };
}

export function Wildcard(field, pattern) {
  return {
    kind: "wildcard",
    field,
    pattern,
    match(index) {
      const re = wildcardToRegex(pattern);
      const set = new Set();
      index.docs.forEach((doc, i) => {
        if (doc[field].some((t) => re.test(t))) set.add(i);
      });
      return set;
    },
  };
}

export function Phrase(field, words, slop = 1) {
  return {
    kind: "phrase",
    field,
    words,
    slop,
    match(index) {
      const set = new Set();
      index.docs.forEach((doc, i) => {
        if (phraseMatches(doc[field], words, slop)) set.add(i);
      });
      return set;
    },
  };
}

// Words must appear in order; the span (last-first) may exceed the minimum
// (n-1) by at most slop-1 extra positions.
function phraseMatches(terms, words, slop) {
  const positions = words.map((w) => {
    const ps = [];
    terms.forEach((t, i) => {
      if (t === w) ps.push(i);
    });
    return ps;
  });
  if (positions.some((ps) => ps.length === 0)) return false;
  const n = words.length;
  const stack = [];
  const search = (wi, minPos) => {
    if (wi === n) {
      return stack[n - 1] - stack[0] - (n - 1) <= slop - 1;
    }
    for (const p of positions[wi]) {
      if (p <= minPos) continue;
      // Prune: even the tightest completion must satisfy the slop.
      if (wi > 0 && p - stack[0] - (n - 1) > slop - 1) continue;
      stack[wi] = p;
      if (search(wi + 1, p)) return true;
    }
    return false;
  };
  return search(0, -1);
}

export function TermRange(field, start, end, startExcl, endExcl) {
  return {
    kind: "range",
    field,
    start,
    end,
    startExcl,
    endExcl,
    match(index) {
      const set = new Set();
      index.docs.forEach((doc, i) => {
        for (const t of doc[field]) {
          if (start !== null && (startExcl ? t <= start : t < start)) continue;
          if (end !== null && (endExcl ? t >= end : t > end)) continue;
          set.add(i);
          break;
        }
      });
      return set;
    },
  };
}

export function Every(field) {
  return {
    kind: "every",
    field,
    match(index) {
      const set = new Set();
      index.docs.forEach((doc, i) => {
        if (doc[field].length > 0) set.add(i);
      });
      return set;
    },
  };
}

export function And(children) {
  return {
    kind: "and",
    children,
    match(index) {
      if (children.length === 0) return new Set();
      let acc = children[0].match(index);
      for (let i = 1; i < children.length && acc.size > 0; i++) {
        const s = children[i].match(index);
        acc = new Set([...acc].filter((d) => s.has(d)));
      }
      return acc;
    },
  };
}

export function Or(children) {
  return {
    kind: "or",
    children,
    match(index) {
      const acc = new Set();
      for (const c of children) {
        for (const d of c.match(index)) acc.add(d);
      }
      return acc;
    },
  };
}

// Negation over the whole index (every document, even ones with no terms
// in any field, matches when the child does not).
export function Not(child) {
  return {
    kind: "not",
    child,
    match(index) {
      const s = child.match(index);
      const acc = allDocs(index);
      for (const d of s) acc.delete(d);
      return acc;
    },
  };
}

