// Query parser replicating the observed behavior of whoosh's QueryParser
// with its default plugin set: whitespace tokenization, double-quoted
// phrases (with optional ~slop), single-quoted terms, field: prefixes,
// * ? wildcards, * (Every), [a TO b] / {a TO b} ranges, ^boost (ignored
// for matching), parentheses, and the AND / OR / NOT operators.
//
// Observed combination rules:
//   - bare terms in a group combine with AND (not OR);
//   - NOT is a prefix operator binding the next atom;
//   - AND and OR are infix operators combining their immediate neighbors,
//     AND having higher priority than OR.

import { analyze, analyzeFilters } from "./analysis.mjs";
import * as q from "./queries.mjs";

const WS = /\s/;
const WORD_END = /[\s()]/;

// --- Scanner -------------------------------------------------------------

function scan(text, schema) {
  const tokens = [];
  const n = text.length;
  let i = 0;
  let pendingField = null;

  const fieldAt = (pos) => {
    // A valid "name:" prefix starting at pos; returns the name or null.
    const m = /^([A-Za-z_][A-Za-z0-9_]*):/.exec(text.slice(pos));
    if (m && schema.names.has(m[1])) return m[1];
    return null;
  };

  while (i < n) {
    const c = text[i];
    if (WS.test(c)) {
      i++;
      continue;
    }

    // field: prefix attached to the following atom.
    if (/[A-Za-z_]/.test(c)) {
      const f = fieldAt(i);
      if (f !== null && i + f.length + 1 < n && !WORD_END.test(text[i + f.length + 1])) {
        pendingField = f;
        i += f.length + 1;
        continue;
      }
      if (f !== null && i + f.length + 1 < n && /["'[{(*]/.test(text[i + f.length + 1])) {
        pendingField = f;
        i += f.length + 1;
        continue;
      }
    }

    if (c === "(") {
      tokens.push({ type: "lparen", field: pendingField });
      pendingField = null;
      i++;
      continue;
    }
    if (c === ")") {
      tokens.push({ type: "rparen" });
      i++;
      skipBoost();
      continue;
    }
    if (c === '"' || c === "'") {
      const quote = c;
      let j = i + 1;
      while (j < n && text[j] !== quote) j++;
      const inner = text.slice(i + 1, j);
      i = j < n ? j + 1 : j;
      let slop = 1;
      if (quote === '"') {
        const sm = /^~(\d+(?:\.\d+)?)/.exec(text.slice(i));
        if (sm) {
          slop = Math.max(1, Math.floor(parseFloat(sm[1])));
          i += sm[0].length;
        }
      }
      skipBoost();
      tokens.push({
        type: quote === '"' ? "phrase" : "squote",
        text: inner,
        slop,
        field: pendingField,
      });
      pendingField = null;
      continue;
    }
    if (c === "[" || c === "{") {
      let j = i + 1;
      while (j < n && text[j] !== "]" && text[j] !== "}") j++;
      if (j < n) {
        const inner = text.slice(i + 1, j);
        const endExcl = text[j] === "}";
        const startExcl = c === "{";
        i = j + 1;
        skipBoost();
        const parts = inner.split(/\s+TO\s+/);
        if (parts.length === 2) {
          tokens.push({
            type: "range",
            start: parts[0].trim() === "" ? null : parts[0].trim(),
            end: parts[1].trim() === "" ? null : parts[1].trim(),
            startExcl,
            endExcl,
            field: pendingField,
          });
        } else {
          tokens.push({ type: "word", text: inner, field: pendingField });
        }
        pendingField = null;
        continue;
      }
      // Unmatched bracket: fall through, treated as a plain word.
    }

    // Plain word (may contain operators, wildcards, boost, '*').
    {
      let j = i;
      while (j < n && !WORD_END.test(text[j])) j++;
      let w = text.slice(i, j);
      i = j;
      // Boost suffix is stripped (boosts do not affect matching).
      w = w.replace(/\^\d+(?:\.\d+)?$/, "");
      if (pendingField === null && (w === "AND" || w === "OR" || w === "NOT")) {
        tokens.push({ type: "op", op: w });
        continue;
      }
      if (w === "*") {
        tokens.push({ type: "star", field: pendingField });
        pendingField = null;
        continue;
      }
      if (w.includes("*") || w.includes("?")) {
        tokens.push({ type: "wildcard", text: w, field: pendingField });
        pendingField = null;
        continue;
      }
      tokens.push({ type: "word", text: w, field: pendingField });
      pendingField = null;
      continue;
    }
  }

  function skipBoost() {
    const bm = /^\^\d+(?:\.\d+)?/.exec(text.slice(i));
    if (bm) i += bm[0].length;
  }

  return tokens;
}

// --- Grouping (parentheses) ----------------------------------------------

function buildTree(tokens) {
  const root = { type: "group", field: null, children: [] };
  const stack = [root];
  for (const tok of tokens) {
    const current = stack[stack.length - 1];
    if (tok.type === "lparen") {
      const g = { type: "group", field: tok.field, children: [] };
      current.children.push(g);
      stack.push(g);
    } else if (tok.type === "rparen") {
      if (stack.length > 1) stack.pop();
      // A stray ')' is ignored.
    } else {
      current.children.push(tok);
    }
  }
  return root;
}

// --- Resolution to query objects -----------------------------------------

function resolveGroup(group, defaultField, inheritedField) {
  const field = group.field !== null ? group.field : inheritedField;

  // Convert atoms to queries; drop tokens that analyze to nothing.
  const items = [];
  for (const child of group.children) {
    if (child.type === "op") {
      items.push(child);
      continue;
    }
    const query = resolveAtom(child, defaultField, field);
    if (query !== null) items.push({ type: "query", query });
  }

  // NOT: prefix, binds the next query.
  let list = [];
  for (let k = 0; k < items.length; k++) {
    const it = items[k];
    if (it.type === "op" && it.op === "NOT") {
      const next = items[k + 1];
      if (next !== undefined && next.type === "query") {
        list.push({ type: "query", query: q.Not(next.query) });
        k++;
      }
      // NOT without a following query is dropped.
    } else {
      list.push(it);
    }
  }

  // Infix operators combining immediate neighbors, AND before OR.
  list = foldInfix(list, "AND", (a, b) => q.And([a, b]));
  list = foldInfix(list, "OR", (a, b) => q.Or([a, b]));

  const queries = list.filter((it) => it.type === "query").map((it) => it.query);
  if (queries.length === 0) return null;
  if (queries.length === 1) return queries[0];
  return q.And(queries);
}

function foldInfix(items, op, combine) {
  let list = items;
  for (;;) {
    const idx = list.findIndex((it) => it.type === "op" && it.op === op);
    if (idx === -1) return list;
    const left = list[idx - 1];
    const right = list[idx + 1];
    if (left !== undefined && left.type === "query" &&
        right !== undefined && right.type === "query") {
      list = [
        ...list.slice(0, idx - 1),
        { type: "query", query: combine(left.query, right.query) },
        ...list.slice(idx + 2),
      ];
    } else {
      // Operator without both neighbors is dropped.
      list = [...list.slice(0, idx), ...list.slice(idx + 1)];
    }
  }
}

function resolveAtom(tok, defaultField, inheritedField) {
  const field = tok.field !== null && tok.field !== undefined ? tok.field
    : inheritedField !== null ? inheritedField
    : defaultField;

  switch (tok.type) {
    case "group":
      return resolveGroup(tok, defaultField, inheritedField);

    case "word":
    case "squote": {
      const terms = analyze(tok.text);
      if (terms.length === 0) return null;
      if (terms.length === 1) return q.Term(field, terms[0]);
      return q.And(terms.map((t) => q.Term(field, t)));
    }

    case "wildcard": {
      const pattern = analyzeFilters(tok.text);
      if (pattern === null) return null;
      return q.Wildcard(field, pattern);
    }

    case "phrase": {
      const terms = analyze(tok.text);
      if (terms.length === 0) return null;
      if (terms.length === 1) return q.Term(field, terms[0]);
      return q.Phrase(field, terms, tok.slop);
    }

    case "range": {
      const start = tok.start === null ? null : analyzeFilters(tok.start);
      const end = tok.end === null ? null : analyzeFilters(tok.end);
      return q.TermRange(field, start, end, tok.startExcl, tok.endExcl);
    }

    case "star":
      return q.Every(field);

    default:
      return null;
  }
}

// --- Public API ----------------------------------------------------------

export class QueryParser {
  constructor(defaultField, schema) {
    this.defaultField = defaultField;
    this.schema = schema;
  }

  parse(text) {
    if (typeof text !== "string" || text.trim() === "") return q.NullQuery();
    const tokens = scan(text, this.schema);
    const tree = buildTree(tokens);
    const query = resolveGroup(tree, this.defaultField, null);
    return query === null ? q.NullQuery() : query;
  }
}

