// In-memory reimplementation of the whoosh index/writer/searcher workflow.
// Documents are stored as analyzed term lists (position = array index)
// per field; matching behavior lives in queries.mjs.

import { analyze } from "./analysis.mjs";

// Field type marker. The original uses TEXT(stored=True) for the title and
// TEXT for the content; storage does not affect the observable behavior
// here, but the flag is kept for interface parity.
export function TEXT(options = {}) {
  return { type: "TEXT", stored: Boolean(options.stored) };
}

export class Schema {
  constructor(fields) {
    this.fields = fields;
    this.names = new Set(Object.keys(fields));
  }
}

class IndexWriter {
  constructor(index) {
    this.index = index;
    this.pending = [];
  }

  addDocument(fields) {
    const doc = {};
    for (const name of this.index.schema.names) {
      doc[name] = analyze(fields[name] !== undefined ? fields[name] : "");
    }
    this.pending.push(doc);
  }

  commit() {
    for (const doc of this.pending) this.index.docs.push(doc);
    this.pending = [];
  }
}

class Searcher {
  constructor(index) {
    this.index = index;
  }

  // Returns an array of matching document numbers; its length mirrors
  // len(results) in the original program.
  search(query) {
    if (query === null || query === undefined) return [];
    return [...query.match(this.index)].sort((a, b) => a - b);
  }
}

class Index {
  constructor(schema) {
    this.schema = schema;
    this.docs = [];
  }

  writer() {
    return new IndexWriter(this);
  }

  searcher() {
    return new Searcher(this);
  }
}

// The original creates the index in a temporary directory; the storage
// location is not observable in the program output, so the index is kept
// in memory. The dirname argument is accepted for interface parity.
export function createIn(dirname, schema) {
  return new Index(schema);
}

