// Minimal reimplementation of the Python argparse behavior used by the
// original script: ten required string options --a .. --j, plus -h/--help.
// Error and help output (including the exact usage wrapping and program
// name) matches the reference executable; errors exit with status 2.

const PROG = "test18_executable";
const LETTERS = ["a", "b", "c", "d", "e", "f", "g", "h", "i", "j"];

const USAGE =
  `usage: ${PROG} [-h] --a A --b B --c C --d D --e E --f F --g G --h H\n` +
  `                         --i I --j J`;

const HELP =
  `${USAGE}\n` +
  `\n` +
  `options:\n` +
  `  -h, --help  show this help message and exit\n` +
  LETTERS.map((l) => `  --${l} ${l.toUpperCase()}`).join("\n") +
  `\n`;

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function printHelpAndExit() {
  process.stdout.write(HELP);
  process.exit(0);
}

function errorAndExit(message) {
  process.stderr.write(`${USAGE}\n${PROG}: error: ${message}\n`);
  process.exit(2);
}

// Mirrors argparse: a token is option-like when it starts with '-', unless
// it is a lone '-', a negative number (the parser has no number-like
// options), or contains a space.
function looksLikeOption(token) {
  if (!token.startsWith("-") || token === "-") return false;
  if (NEGATIVE_NUMBER.test(token)) return false;
  if (token.includes(" ")) return false;
  return true;
}

export function parseArgs(argv) {
  const values = {};
  const extras = [];
  let optionsDone = false;

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (!optionsDone && token === "--") {
      optionsDone = true;
      continue;
    }

    if (!optionsDone && token === "-h") {
      printHelpAndExit();
    }

    if (!optionsDone && token.startsWith("--") && token.length > 2) {
      const body = token.slice(2);
      const eq = body.indexOf("=");
      const name = eq === -1 ? body : body.slice(0, eq);

      if (name === "help") {
        printHelpAndExit();
      }

      if (LETTERS.includes(name)) {
        if (eq !== -1) {
          values[name] = body.slice(eq + 1);
        } else {
          const next = argv[i + 1];
          if (next === undefined || looksLikeOption(next)) {
            errorAndExit(`argument --${name}: expected one argument`);
          }
          values[name] = next;
          i++;
        }
      } else {
        extras.push(token);
      }
      continue;
    }

    if (!optionsDone && looksLikeOption(token)) {
      // Unknown short-option-style token.
      extras.push(token);
      continue;
    }

    extras.push(token);
  }

  const missing = LETTERS.filter((l) => !(l in values));
  if (missing.length > 0) {
    errorAndExit(
      `the following arguments are required: ${missing.map((l) => `--${l}`).join(", ")}`
    );
  }
  if (extras.length > 0) {
    errorAndExit(`unrecognized arguments: ${extras.join(" ")}`);
  }

  return values;
}

