// Node.js (ESM) port of /workspace/dataset/test18.py.
// Indexes ten documents from command-line arguments and prints the total
// number of search hits when each value is run as a query.

import { parseArgs } from "./argparse.mjs";
import { Schema, TEXT, createIn } from "./whoosh/index.mjs";
import { QueryParser } from "./whoosh/qparser.mjs";

const args = parseArgs(process.argv.slice(2));

const schema = new Schema({ title: TEXT({ stored: true }), content: TEXT() });
const ix = createIn(null, schema);
const writer = ix.writer();
const inputs = ["a", "b", "c", "d", "e", "f", "g", "h", "i", "j"].map(
  (letter) => args[letter]
);
inputs.forEach((val, i) => {
  writer.addDocument({ title: `doc${i}`, content: val });
});
writer.commit();

const searcher = ix.searcher();
let count = 0;
for (const val of inputs) {
  const query = new QueryParser("content", ix.schema).parse(val);
  const results = searcher.search(query);
  count += results.length;
}
console.log(count);

