// Random test-case generator: prints N lines, each with 10 tab-separated args.
const vocab = [
  "hello", "world", "quick", "brown", "fox", "red", "blue", "green",
  "cat", "dog", "apple", "banana", "data", "test", "node", "python",
];
const stop = ["the", "a", "and", "or", "not", "is", "to", "in", "with"];
const shorts = ["x", "y", "z", "q", "7"];
const punct = [",", ".", "-", "+", ":", ";", "!", "/"];
const unicode = ["café", "NAÏVE", "über", "東京", "ß"];

function pick(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
function chance(p) { return Math.random() < p; }

function term() {
  const r = Math.random();
  if (r < 0.55) return pick(vocab);
  if (r < 0.65) return pick(stop);
  if (r < 0.70) return pick(shorts);
  if (r < 0.75) return pick(unicode);
  if (r < 0.80) return pick(vocab) + pick(punct) + pick(vocab);
  if (r < 0.84) return pick(vocab) + "*";
  if (r < 0.87) return pick(vocab).slice(0, 3) + "?";
  if (r < 0.90) return "*" + pick(vocab).slice(2);
  if (r < 0.93) return pick(vocab) + "^" + (1 + Math.floor(Math.random() * 3));
  if (r < 0.96) return pick(["title:", "content:", "nosuch:"]) + pick(vocab);
  return pick(vocab) + Math.floor(Math.random() * 100);
}

function value() {
  const r = Math.random();
  if (r < 0.04) return "";
  if (r < 0.08) return '"' + term() + " " + term() + '"';
  if (r < 0.10) return '"' + term() + " " + term() + '"~' + (1 + Math.floor(Math.random() * 3));
